  // ═══ NCERT Class 8 Deepakam Part 3 ═══
  "ncert-deepakam-8": [
    { id: "ch-deepakam-8-1", bookId: "ncert-deepakam-8", chapterNumber: 1, title: "Sangacchadhvam Samvadadhvam", titleSanskrit: "\u0938\u0902\u0917\u091A\u094D\u091B\u0927\u094D\u0935\u0902 \u0938\u0902\u0935\u0926\u0927\u094D\u0935\u092E\u094D", verseCount: 8, contentPreview: "Walk together, speak together" },
    { id: "ch-deepakam-8-2", bookId: "ncert-deepakam-8", chapterNumber: 2, title: "Alpanamapi Vastunam Samhatih Karyasadhika", titleSanskrit: "\u0905\u0932\u094D\u092A\u093E\u0928\u093E\u092E\u092A\u093F \u0935\u0938\u094D\u0924\u0942\u0928\u093E\u0902 \u0938\u0902\u0939\u0924\u093F\u0903 \u0915\u093E\u0930\u094D\u092F\u0938\u093E\u0927\u093F\u0915\u093E", verseCount: 8, contentPreview: "Union of small things accomplishes great works" },
    { id: "ch-deepakam-8-3", bookId: "ncert-deepakam-8", chapterNumber: 3, title: "Subhashitarasam Pitva Jivanam Saphalam Kuru", titleSanskrit: "\u0938\u0941\u092D\u093E\u0937\u093F\u0924\u0930\u0938\u0902 \u092A\u0940\u0924\u094D\u0935\u093E \u091C\u0940\u0935\u0928\u0902 \u0938\u092B\u0932\u0902 \u0915\u0941\u0930\u0941", verseCount: 10, contentPreview: "Drink the essence of wise sayings and make life successful" },
    { id: "ch-deepakam-8-4", bookId: "ncert-deepakam-8", chapterNumber: 4, title: "Pranamyo Deshabhakto Gopabandhur Mahamanah", titleSanskrit: "\u092A\u094D\u0930\u0923\u092E\u094D\u092F\u094B \u0926\u0947\u0936\u092D\u0915\u094D\u0924\u094B\u093D\u092F\u0902 \u0917\u094B\u092A\u092C\u0928\u094D\u0927\u0941\u0930\u094D\u092E\u0939\u093E\u092E\u0928\u093E\u0903", verseCount: 10, contentPreview: "Salute this patriot, the great-souled Gopabandhu" },
    { id: "ch-deepakam-8-5", bookId: "ncert-deepakam-8", chapterNumber: 5, title: "Gita Sugita Kartavya", titleSanskrit: "\u0917\u0940\u0924\u093E \u0938\u0941\u0917\u0940\u0924\u093E \u0915\u0930\u094D\u0924\u0935\u094D\u092F\u093E", verseCount: 10, contentPreview: "The Gita should be well sung" },
    { id: "ch-deepakam-8-6", bookId: "ncert-deepakam-8", chapterNumber: 6, title: "Digibharatam Yugaparivartanam", titleSanskrit: "\u0921\u093F\u091C\u093F\u092D\u093E\u0930\u0924\u092E\u094D \u2013 \u092F\u0941\u0917\u092A\u0930\u093F\u0935\u0930\u094D\u0924\u0928\u092E\u094D", verseCount: 10, contentPreview: "Digital India - a changing era" },
    { id: "ch-deepakam-8-7", bookId: "ncert-deepakam-8", chapterNumber: 7, title: "Manjulamanjusha Sundarasurabhasha", titleSanskrit: "\u092E\u091E\u094D\u091C\u0941\u0932\u092E\u091E\u094D\u091C\u0942\u0937\u093E \u0938\u0941\u0928\u094D\u0926\u0930\u0938\u0941\u0930\u092D\u093E\u0937\u093E", verseCount: 8, contentPreview: "Beautiful casket, lovely fragrance" },
    { id: "ch-deepakam-8-8", bookId: "ncert-deepakam-8", chapterNumber: 8, title: "Pashyata Konamaishanyam Bharatasya Manoharam", titleSanskrit: "\u092A\u0936\u094D\u092F\u0924 \u0915\u094B\u0923\u092E\u0948\u0936\u093E\u0928\u094D\u092F\u0902 \u092D\u093E\u0930\u0924\u0938\u094D\u092F \u092E\u0928\u094B\u0939\u0930\u092E\u094D", verseCount: 10, contentPreview: "Behold the charming north-east corner of India" },
    { id: "ch-deepakam-8-9", bookId: "ncert-deepakam-8", chapterNumber: 9, title: "Ko Ruk? Ko Ruk? Ko Ruk?", titleSanskrit: "\u0915\u094B\u093D\u0930\u0941\u0915\u094D? \u0915\u094B\u093D\u0930\u0941\u0915\u094D? \u0915\u094B\u093D\u0930\u0941\u0915\u094D?", verseCount: 10, contentPreview: "Who is ill? Who is ill? Who is ill?" },
    { id: "ch-deepakam-8-10", bookId: "ncert-deepakam-8", chapterNumber: 10, title: "Sannimitte Varam Tyagah Ka Bhagah", titleSanskrit: "\u0938\u0928\u094D\u0928\u093F\u092E\u093F\u0924\u094D\u0924\u0947 \u0935\u0930\u0902 \u0924\u094D\u092F\u093E\u0917\u0903 (\u0915-\u092D\u093E\u0917\u0903)", verseCount: 10, contentPreview: "Better to renounce for a good cause (Part 1)" },
    { id: "ch-deepakam-8-11", bookId: "ncert-deepakam-8", chapterNumber: 11, title: "Sannimitte Varam Tyagah Kha Bhagah", titleSanskrit: "\u0938\u0928\u094D\u0928\u093F\u092E\u093F\u0924\u094D\u0924\u0947 \u0935\u0930\u0902 \u0924\u094D\u092F\u093E\u0917\u0903 (\u0916-\u092D\u093E\u0917\u0903)", verseCount: 10, contentPreview: "Better to renounce for a good cause (Part 2)" },
    { id: "ch-deepakam-8-12", bookId: "ncert-deepakam-8", chapterNumber: 12, title: "Samyagvarnaprayogena Brahmaloke Mahiyate", titleSanskrit: "\u0938\u092E\u094D\u092F\u0917\u094D\u0935\u0930\u094D\u0923\u092A\u094D\u0930\u092F\u094B\u0917\u0947\u0923 \u092C\u094D\u0930\u0939\u094D\u092E\u0932\u094B\u0915\u0947 \u092E\u0939\u0940\u092F\u0924\u0947", verseCount: 10, contentPreview: "Through correct utterance of letters one is honoured in Brahma-loka" },
    { id: "ch-deepakam-8-13", bookId: "ncert-deepakam-8", chapterNumber: 13, title: "Varnoccharana-Shiksha 1", titleSanskrit: "\u0935\u0930\u094D\u0923\u094B\u091A\u094D\u091A\u093E\u0930\u0923-\u0936\u093F\u0915\u094D\u0937\u093E \u0967", verseCount: 8, contentPreview: "Pronunciation training 1" },
    { id: "ch-deepakam-8-14", bookId: "ncert-deepakam-8", chapterNumber: 14, title: "Parishishtam 1: Vyakaranam", titleSanskrit: "\u092A\u0930\u093F\u0936\u093F\u0937\u094D\u091F\u092E\u094D \u0967: \u0935\u094D\u092F\u093E\u0915\u0930\u0923\u092E\u094D", verseCount: 8, contentPreview: "Appendix 1: Grammar" },
    { id: "ch-deepakam-8-15", bookId: "ncert-deepakam-8", chapterNumber: 15, title: "Parishishtam 2: Shabdarupani", titleSanskrit: "\u092A\u0930\u093F\u0936\u093F\u0937\u094D\u091F\u092E\u094D \u0968: \u0936\u092C\u094D\u0926\u0930\u0942\u092A\u093E\u0923\u093F", verseCount: 8, contentPreview: "Appendix 2: Noun declensions" },
    { id: "ch-deepakam-8-16", bookId: "ncert-deepakam-8", chapterNumber: 16, title: "Parishishtam 3: Dhaturupani", titleSanskrit: "\u092A\u0930\u093F\u0936\u093F\u0937\u094D\u091F\u092E\u094D \u0969: \u0927\u093E\u0924\u0941\u0930\u0942\u092A\u093E\u0923\u093F", verseCount: 8, contentPreview: "Appendix 3: Verb conjugations" }
  ],
